using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    // --- FormatPhoneNumber ---

    [TestMethod]
    public void FormatPhoneNumber_ReturnsParenthesizedAreaCode()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        StringAssert.StartsWith(result, "(555)");
    }

    [TestMethod]
    public void FormatPhoneNumber_EndsWithLastFourDigits()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        StringAssert.EndsWith(result, "4567");
    }

    [TestMethod]
    public void FormatPhoneNumber_ContainsDashSeparator()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        StringAssert.Contains(result, "-");
    }

    [TestMethod]
    public void FormatPhoneNumber_MatchesFullPattern()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        StringAssert.Matches(result, new(@"^\(\d{3}\) \d{3}-\d{4}$"));
    }

    [TestMethod]
    public void FormatPhoneNumber_ExactOutput()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        Assert.AreEqual("(555) 123-4567", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    public void FormatPhoneNumber_WrongLength_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.FormatPhoneNumber("123"));
    }

    // --- BuildGreeting ---

    [TestMethod]
    public void BuildGreeting_StartsWithDear()
    {
        var result = _formatter.BuildGreeting("Smith");

        StringAssert.StartsWith(result, "Dear ");
    }

    [TestMethod]
    public void BuildGreeting_EndsWithComma()
    {
        var result = _formatter.BuildGreeting("Smith");

        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    public void BuildGreeting_ContainsName()
    {
        var result = _formatter.BuildGreeting("Smith");

        StringAssert.Contains(result, "Smith");
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_UsesMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        StringAssert.Contains(result, "Mr.");
        Assert.AreEqual("Dear Mr. Smith,", result);
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle()
    {
        var result = _formatter.BuildGreeting("Jones", "Dr.");

        StringAssert.StartsWith(result, "Dear Dr.");
        Assert.AreEqual("Dear Dr. Jones,", result);
    }

    [TestMethod]
    public void BuildGreeting_WhitespaceName_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.BuildGreeting("   "));
    }

    // --- GenerateSlug ---

    [TestMethod]
    public void GenerateSlug_LowercasesOutput()
    {
        var result = _formatter.GenerateSlug("Hello World");

        StringAssert.DoesNotMatch(result, new("[A-Z]"));
    }

    [TestMethod]
    public void GenerateSlug_ReplacesSpacesWithDashes()
    {
        var result = _formatter.GenerateSlug("Hello World");

        StringAssert.Contains(result, "-");
        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_StripsSpecialCharacters()
    {
        var result = _formatter.GenerateSlug("C# is Great!!");

        StringAssert.Matches(result, new(@"^[a-z0-9\-]+$"));
        Assert.AreEqual("c-is-great", result);
    }

    [TestMethod]
    public void GenerateSlug_TrimsLeadingAndTrailingDashes()
    {
        var result = _formatter.GenerateSlug("  --Hello--  ");

        Assert.IsFalse(result.StartsWith('-'));
        Assert.IsFalse(result.EndsWith('-'));
        Assert.AreEqual("hello", result);
    }

    [TestMethod]
    public void GenerateSlug_CollapsesConsecutiveSpecialChars()
    {
        var result = _formatter.GenerateSlug("one   two---three");

        StringAssert.DoesNotMatch(result, new("--"));
        Assert.AreEqual("one-two-three", result);
    }

    [TestMethod]
    public void GenerateSlug_WhitespaceInput_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.GenerateSlug("   "));
    }

    // --- FormatCurrency ---

    [TestMethod]
    public void FormatCurrency_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(9.99m);

        StringAssert.StartsWith(result, "$");
    }

    [TestMethod]
    public void FormatCurrency_EndsWithTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(10m);

        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_MatchesCurrencyPattern()
    {
        var result = _formatter.FormatCurrency(1234.5m);

        StringAssert.Matches(result, new(@"^\$\d+\.\d{2}$"));
        Assert.AreEqual("$1234.50", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol()
    {
        var result = _formatter.FormatCurrency(19.99m, "€");

        StringAssert.StartsWith(result, "€");
        Assert.AreEqual("€19.99", result);
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount()
    {
        var result = _formatter.FormatCurrency(-5.50m);

        StringAssert.StartsWith(result, "$-");
        Assert.AreEqual("$-5.50", result);
    }

    [TestMethod]
    public void FormatCurrency_ZeroAmount()
    {
        var result = _formatter.FormatCurrency(0m);

        Assert.AreEqual("$0.00", result);
    }
}

